CREATE OR REPLACE FUNCTION public.assign_contractor_to_storm(p_storm_id uuid, p_contractor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE revision uuid;
BEGIN
  IF NOT private.has_permission(auth.uid(),'admin.assignments.edit') THEN RAISE EXCEPTION 'Only authorized users can assign contractors'; END IF;
  PERFORM 1 FROM public.storm_events WHERE id=p_storm_id AND NOT is_deleted FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Create a storm first'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.contractors WHERE id=p_contractor_id AND onboarding_status::text='APPROVED' AND is_eligible_for_assignment) THEN RAISE EXCEPTION 'Select an approved, eligible contractor'; END IF;
  SELECT id INTO revision FROM public.storm_event_roster_revisions WHERE storm_event_id=p_storm_id AND NOT is_locked ORDER BY revision_number DESC LIMIT 1;
  IF revision IS NULL THEN
    IF EXISTS(SELECT 1 FROM public.storm_event_roster_revisions WHERE storm_event_id=p_storm_id) THEN RAISE EXCEPTION 'The storm roster is locked. Create an unlocked roster revision first'; END IF;
    INSERT INTO public.storm_event_roster_revisions(storm_event_id,revision_number,revision_label,created_by) VALUES(p_storm_id,0,'Initial roster',auth.uid()) RETURNING id INTO revision;
  END IF;
  IF EXISTS(SELECT 1 FROM public.storm_event_roster_members WHERE roster_revision_id=revision AND contractor_id=p_contractor_id AND member_status<>'REMOVED') THEN RETURN; END IF;
  INSERT INTO public.storm_event_roster_members(roster_revision_id,contractor_id,member_status,created_by) VALUES(revision,p_contractor_id,'CONFIRMED',auth.uid());
END $function$

CREATE OR REPLACE FUNCTION public.create_storm_ticket(p_storm_id uuid, p_common jsonb, p_payload jsonb, p_confidence jsonb DEFAULT '{}'::jsonb, p_warnings text[] DEFAULT '{}'::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE storm public.storm_events%ROWTYPE; ticket_id uuid; number text;
BEGIN
  IF NOT private.has_permission(auth.uid(),'admin.tickets.edit') THEN RAISE EXCEPTION 'Only authorized users can create tickets'; END IF;
  SELECT * INTO storm FROM public.storm_events WHERE id=p_storm_id AND NOT is_deleted FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Create or select a storm first'; END IF;
  PERFORM public.validate_storm_ticket_payload(p_storm_id,p_payload);
  number:=CASE WHEN storm.utility_client='ENTERGY' THEN p_payload->>'incident_number' ELSE p_payload->>'external_ticket_id' END;
  IF coalesce(btrim(number),'')='' THEN RAISE EXCEPTION 'Utility ticket number is required'; END IF;
  INSERT INTO public.tickets(storm_event_id,ticket_number,utility_client,template_key,status,priority,source_type,address,work_description,created_by)
    VALUES(storm.id,number,storm.utility_client,storm.ticket_template_key,
      coalesce(p_common->>'status','DRAFT')::public.ticket_status,coalesce(p_common->>'priority','C')::public.priority_level,
      coalesce(p_common->>'source_type','MANUAL')::public.ticket_source_type,p_payload->>'address_line',storm.name||' - '||number,auth.uid()) RETURNING id INTO ticket_id;
  INSERT INTO public.ticket_payloads(ticket_id,payload,payload_version,extraction_confidence,extraction_warnings)
    VALUES(ticket_id,p_payload,coalesce((storm.config_snapshot->>'payload_version')::integer,1),p_confidence,p_warnings);
  RETURN ticket_id;
END $function$

CREATE OR REPLACE FUNCTION public.finalize_contractor_invite(p_actor_id uuid, p_profile_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text, p_resend boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE contractor_id uuid;
BEGIN
 IF NOT private.has_permission(p_actor_id,'admin.users.edit') THEN RAISE EXCEPTION 'Invitation permission required'; END IF;
 PERFORM 1 FROM public.profiles WHERE id=p_profile_id AND role::text='CONTRACTOR' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Contractor profile required'; END IF;
 UPDATE public.profiles SET first_name=p_first_name,last_name=p_last_name,phone=p_phone,must_reset_password=true WHERE id=p_profile_id;
 SELECT id INTO contractor_id FROM public.contractors WHERE profile_id=p_profile_id;
 IF contractor_id IS NULL THEN
  INSERT INTO public.contractors(profile_id,business_name,business_email,business_phone,onboarding_status,is_eligible_for_assignment)
  VALUES(p_profile_id,p_first_name||' '||p_last_name,p_email,p_phone,'PENDING',false) RETURNING id INTO contractor_id;
 END IF;
 INSERT INTO public.contractor_invitations(profile_id,email,first_name,last_name,invited_by,last_result)
 VALUES(p_profile_id,p_email,p_first_name,p_last_name,p_actor_id,'sent') ON CONFLICT(profile_id) DO UPDATE SET first_name=p_first_name,last_name=p_last_name,sent_at=clock_timestamp(),last_result='sent',invited_by=p_actor_id,send_count=public.contractor_invitations.send_count+1;
 INSERT INTO public.audit_logs(action,entity_type,entity_id,user_id,user_role,new_values,change_summary)
 VALUES(CASE WHEN p_resend THEN 'INVITE_RESENT' ELSE 'INVITE_SENT' END,'contractor_invitation',p_profile_id,p_actor_id,'SUPER_ADMIN',jsonb_build_object('email',p_email,'contractor_id',contractor_id,'result','sent'),'Contractor invitation sent');
 RETURN jsonb_build_object('profile_id',p_profile_id,'contractor_id',contractor_id,'email',p_email,'state','invited');
END $function$
